// Generated by scripts/sync-examples.ts from scripts/example-app/src/demos/files/sandbox.lucent.ts. Do not edit.
// Text notes in the app's sandbox: FileManager in Documents/notes on iOS,
// java.io.File in the app's files/notes directory on Android. Async, so the
// disk is touched on the Lucent thread, never the JavaScript one.
import { PLATFORM } from "lucent:platform";
import {
  FileAttributeKey,
  FileManager,
  FileManager_SearchPathDirectory as Directory,
  FileManager_SearchPathDomainMask as Domain,
} from "lucent:ios/Foundation";
import { asDate, asNumber } from "lucent:ios";
import { File } from "lucent:android/java.io";
import { AtomicFile } from "lucent:android/android.util";
import { appContext } from "lucent:android";
import { error, utf8Decode, utf8Encode } from "lucent:core";

export interface Note {
  name: string;
  bytes: number;
  /** Milliseconds since the epoch. */
  modified: number;
}

const FOLDER = "notes";

// --- iOS ---------------------------------------------------------------------

function iosDirectory(): string {
  const documents = FileManager.default.urls(Directory.documentDirectory, Domain.userDomainMask)[0]
    ?.path;
  if (!documents) throw error("ERR_FILES", "No Documents directory");

  const dir = `${documents}/${FOLDER}`;
  FileManager.default.createDirectory(dir, true, null);

  return dir;
}

function iosNote(dir: string, name: string): Note {
  const attributes = FileManager.default.attributesOfItem(`${dir}/${name}`);

  return {
    name,
    bytes: asNumber(attributes[FileAttributeKey.size] ?? null) ?? 0,
    modified: asDate(attributes[FileAttributeKey.modificationDate] ?? null)?.getTime() ?? 0,
  };
}

// --- Android -----------------------------------------------------------------

function androidDirectory(): File {
  const files = appContext().getFilesDir();
  if (!files) throw error("ERR_FILES", "No files directory");

  const dir = new File(files, FOLDER);
  dir.mkdirs();

  return dir;
}

// --- The module --------------------------------------------------------------

/** Where the notes are, as an absolute path. */
export async function directoryAsync(): Promise<string> {
  return PLATFORM === "ios" ? iosDirectory() : androidDirectory().getAbsolutePath();
}

/** Every note, the most recently changed first. */
export async function listAsync(): Promise<Note[]> {
  let notes: Note[] = [];

  if (PLATFORM === "ios") {
    const dir = iosDirectory();
    notes = FileManager.default.contentsOfDirectory(dir).map((name) => iosNote(dir, name));
  } else {
    // list(), not listFiles(): Lucent does not bind SDK calls returning File[] yet.
    const dir = androidDirectory();
    for (const name of dir.list() ?? []) {
      const file = new File(dir, name);
      notes.push({ name, bytes: Number(file.length()), modified: Number(file.lastModified()) });
    }
  }

  return notes.sort((a, b) => b.modified - a.modified);
}

export async function writeAsync(name: string, text: string): Promise<void> {
  const bytes = utf8Encode(text);

  if (PLATFORM === "ios") {
    if (!FileManager.default.createFile(`${iosDirectory()}/${name}`, bytes, null))
      throw error("ERR_FILES", `Could not write ${name}`);
  } else {
    const file = new AtomicFile(new File(androidDirectory(), name));
    const out = file.startWrite();
    if (!out) throw error("ERR_FILES", `Could not write ${name}`);

    try {
      out.write(bytes);
      file.finishWrite(out);
    } catch (e) {
      file.failWrite(out);
      throw e;
    }
  }
}

/** The note's text, or null if there is no such note. */
export async function readAsync(name: string): Promise<string | null> {
  if (PLATFORM === "ios") {
    const bytes = FileManager.default.contents(`${iosDirectory()}/${name}`);
    return bytes ? utf8Decode(bytes) : null;
  } else {
    const file = new File(androidDirectory(), name);
    if (!file.exists()) return null;

    const bytes = new AtomicFile(file).readFully();
    return bytes ? utf8Decode(bytes) : null;
  }
}

export async function deleteAsync(name: string): Promise<void> {
  if (PLATFORM === "ios") {
    FileManager.default.removeItem(`${iosDirectory()}/${name}`);
  } else {
    if (!new File(androidDirectory(), name).delete())
      throw error("ERR_FILES", `Could not delete ${name}`);
  }
}
